index 1316978e2..9434eac36 100644
--- a/ggml/src/ggml-cpu/CMakeLists.txt
+++ b/ggml/src/ggml-cpu/CMakeLists.txt
@@ -714,6 +714,67 @@ function(ggml_add_cpu_backend_variant_impl tag_name)
         list(APPEND GGML_CPU_SOURCES ${GGML_KLEIDIAI_SOURCES})
     endif()

+    # andesim (ROADMAP_LINUX_RUNTIME.md U9): on riscv64 with GGML_RVV, GCC's
+    # auto-vectorizer (specifically the SLP/straight-line pass, not the
+    # loop vectorizer -- confirmed by testing both `-fno-tree-vectorize`
+    # and a #pragma GCC push_options/optimize/pop_options wrapper, neither
+    # of which stopped it) lowers ordinary struct/array copies in generic
+    # dispatch/bookkeeping code (found: a struct-literal static init in
+    # ggml-cpu.cpp registering the CPU backend's device vtable, and an
+    # array copy in ggml-cpu.c's ggml_graph_plan) into 64-bit-element (e64)
+    # vector loads/stores. That is correct for any core meeting the RISC-V
+    # V extension's own spec-mandated ELEN>=64 floor, but the andesim
+    # hybrid-sim target (Andes ax45mpv) implements only Zve32f (ELEN=32)
+    # and traps on it.
+    #
+    # Rather than keep hunting individual auto-vectorized sites one at a
+    # time (whack-a-mole, with no way to be sure the next one has been
+    # found), this is inverted: DENY vector codegen by default for every
+    # generic/dispatch file (no computational reason for any of them to
+    # need a specific ELEN), and explicitly ALLOW-LIST only the files
+    # confirmed (by their own genuine, hand-written __riscv_v* intrinsic
+    # kernels -- not guessed) to need full v: vec.cpp and repack.cpp, and
+    # arch/riscv/{quants,repack}.cpp/.c (the whole point of the arch/riscv/
+    # split -- hand-written RVV quantization kernels). Everything else in
+    # GGML_CPU_SOURCES is generic op dispatch/graph bookkeeping with no own
+    # RVV code, so constraining it is free and closes off the whole bug
+    # class within those files, not just the two instances found here.
+    #
+    # This file-level mechanism does NOT cover every e64/vector-capability
+    # issue on this target -- an allow-listed file can still have individual
+    # functions that are wrong for ELEN=32 (or for this engine's narrower-
+    # than-spec vector-FPU LMUL ceiling; a distinct, RTL-only limit, see
+    # ROADMAP_LINUX_RUNTIME.md U9). Those got fixed AT the function, in the
+    # allow-listed file itself, not here: vec.cpp's ggml_vec_dot_f16/
+    # ggml_vec_dot_bf16 carry a per-function `__attribute__((target(...)))`
+    # override for the same auto-vectorization reason as above (their
+    # scalar fallback path, taken when zvfh/zvfbfwma are unset); vec.cpp's
+    # ggml_vec_cvar_f32/ggml_vec_soft_max_f32 were rewritten to reduce in
+    # native f32 precision instead of an unnecessary e64 widening reduce
+    # (matching every other architecture's branch in the same two
+    # functions, which never needed e64 either); arch/riscv/quants.c's
+    # quantize_row_q8_0/quantize_row_q8_1 now call their portable `_ref`
+    # scalar fallback unconditionally (their hardcoded LMUL=8 float path
+    # exceeds this engine's actual FP vector datapath width). Full story,
+    # including how each was diagnosed: andesim's docs/llama_roi_howto.md.
+    if (GGML_SYSTEM_ARCH STREQUAL "riscv64" AND GGML_RVV)
+        set(ANDESIM_NO_V_MARCH "-march=rv64gc_zicbop_zihintpause")
+        set_source_files_properties(
+            ggml-cpu/ggml-cpu.c
+            ggml-cpu/ggml-cpu.cpp
+            ggml-cpu/hbm.cpp
+            ggml-cpu/quants.c
+            ggml-cpu/traits.cpp
+            ggml-cpu/binary-ops.cpp
+            ggml-cpu/unary-ops.cpp
+            ggml-cpu/ops.cpp
+            PROPERTIES COMPILE_OPTIONS "${ANDESIM_NO_V_MARCH}")
+        # ggml-cpu/repack.cpp (generic -- NOT arch/riscv/repack.cpp) is the
+        # SAME repacking family as the riscv one; keep it on the allow-list
+        # (full v) rather than assume it is safe, since its riscv sibling
+        # was one of the two confirmed-need-e64 files.
+    endif()
+
     message(STATUS "Adding CPU backend variant ${GGML_CPU_NAME}: ${ARCH_FLAGS} ${ARCH_DEFINITIONS}")
     target_sources(${GGML_CPU_NAME} PRIVATE ${GGML_CPU_SOURCES})
     target_compile_options(${GGML_CPU_NAME} PRIVATE ${ARCH_FLAGS})
