// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
// only the built-in qemu descriptor, so it resolves that directly rather than
// discover_engines(), which would spawn a --describe subprocess per Verilator
// build only to discard them all here.
int run_fast(const Cli& cli) {
  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
    std::fprintf(stderr,
                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
                 "got '%s'\n",
                 cli.engine.c_str());
    return 2;
  }
  // --runtime linux (U2, ROADMAP_LINUX_RUNTIME.md) defaults --mem-size to 1G
  // (the app + vlinux's own arenas) when the user did not pick one.
  std::string mem_size_spec = cli.mem_size;
  if (cli.runtime == "linux" && mem_size_spec.empty()) mem_size_spec = "1G";

  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
  // default injected). It precedes the post-`--` args, so a user's own -m wins.
  std::string err;
  std::vector<std::string> extra = qemu_m_args(mem_size_spec, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
    return 2;
  }
  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
  if (cli.gdb) {
    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
    extra.push_back("-gdb");
    extra.push_back("tcp::" + port);
    extra.push_back("-S");
  }

  // --runtime linux: stage a manifested vlinux.elf that boots the app under
  // the proxy kernel. The ELF positional is the APP, not the boot image --
  // -bios loads the staged vlinux instead (run_standalone's boot_elf_override).
  Cli cli2 = cli;
  std::string boot_elf;
  if (cli.runtime == "linux") {
    if (int rc = check_one_elf(cli, "fast")) return rc;
    const std::string app_elf =
        abs_elf(cli.positional[0], "--mode fast --runtime linux");
    if (app_elf.empty()) return 2;

    // mem_size_spec already passed qemu_m_args above (whole-MiB check, a
    // strictly tighter validation than parse_size alone), so this call
    // cannot fail: reused only to get the byte count for the manifest.
    const long long mem_bytes = parse_size(mem_size_spec, err);

    std::string stage_err;
    boot_elf = stage_linux_runtime(app_elf, static_cast<uint64_t>(mem_bytes),
                                   cli.passthrough, stage_err);
    if (boot_elf.empty()) {
      std::fprintf(stderr, "andesim run --mode fast --runtime linux: %s\n",
                   stage_err.c_str());
      return 2;
    }
    log_line(kLogInfo, "[andesim] --runtime linux: staged %s (app=%s)",
             boot_elf.c_str(), app_elf.c_str());

    // App argv (ROADMAP_LINUX_RUNTIME.md U8) travels through the manifest
    // above, not QEMU's own CLI -- clear it here so QEMU never sees it as
    // engine flags (e.g. "-m x.gguf" is not a memory size).
    cli2.passthrough.clear();

    // Engine-synced CPU: the app + vlinux run on the hardware a hybrid
    // measurement targets, not the ax46 vplat default (last -cpu wins).
    extra.push_back("-cpu");
    extra.push_back("andes-ax45mpv,vlen=512");
  }

  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
  // ELF -- the override is the user's call.
  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
  int xlen;
  if (cli.engine == kQemuId32) xlen = 32;
  else if (cli.engine == kQemuId64) xlen = 64;
  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
  // Only an explicit engine can disagree with the ELF (when none is given, xlen
  // == elf_w), so this guard already implies an explicit --engine.
  if (elf_w && elf_w != xlen)
    std::fprintf(stderr,
                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
                 "(running as rv%d)\n",
                 cli.engine.c_str(), xlen, elf_w, xlen);
  return run_standalone(cli2, builtin_qemu_arch(xlen), "fast", extra,
                        /*clean_output=*/false, boot_elf);
}
